# frozen_string_literal: true

require "rails_helper"

RSpec.describe PaymentMailer do
  # "Every invoice, line-item, invoice-tax and payment write, mobile-collection payments included, gets 503 ownership_moving while handoff_step is set and writes nothing"
  it "sends no payment mail and leaves payment_sent_at nil when delivered during a handoff" do
    company = create(:company)
    client = create(:client, company:)
    invoice = create(:invoice, company:, client:, status: :paid)
    expect(invoice.reload.payment_sent_at).to be_nil
    TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).update_all(handoff_step: "reconcile")

    expect {
      expect { described_class.with(invoice_id: invoice.id).payment.deliver_now }
        .to raise_error(Timekeeping::BillingFence::OwnershipMoving)
    }.not_to change { ActionMailer::Base.deliveries.count }
    expect(invoice.reload.payment_sent_at).to be_nil
  end
end
